<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { api, post } from '../api'
import LegacyIcon from './LegacyIcon.vue'
interface GitHubSource { id: string; repo: string; branch: string; path: string; glob: string; enabled: boolean; last_synced_sha: string; last_synced_at: string; last_sync_status: string; last_sync_error: string | null; files_synced: number }
interface WebSource { id: string; url: string; max_depth: number; max_pages: number; enabled: boolean; auto_sync_enabled: boolean; sync_interval_hours: number; page_count: number; last_synced_at: string; last_sync_status: string; last_sync_error: string | null }
const props = defineProps<{ kind: 'github' | 'web'; kbName: string; readOnly?: boolean }>()
const githubSources = ref<GitHubSource[]>([])
const webSources = ref<WebSource[]>([])
const adding = ref(false)
const loading = ref(true)
const busy = ref(false)
const error = ref('')
const notice = ref('')
const github = reactive({ repo: '', branch: 'main', path: '', glob: '*.md' })
const web = reactive({ url: '', max_depth: 3, max_pages: 200, auto_sync_enabled: false, sync_interval_hours: 24 })
const sources = computed(() => props.kind === 'github' ? githubSources.value : webSources.value)
const endpoint = computed(() => props.kind === 'github' ? 'github' : 'web')
async function load() { loading.value = true; error.value = ''; try { const result = await api<GitHubSource[] & WebSource[]>(`/api/knowledge-bases/${encodeURIComponent(props.kbName)}/${endpoint.value}-sources`); if (props.kind === 'github') githubSources.value = result; else webSources.value = result } catch (cause) { error.value = cause instanceof Error ? cause.message : '来源加载失败' } finally { loading.value = false } }
onMounted(load)
async function add() { busy.value = true; error.value = ''; try { if (props.kind === 'github') await post(`/api/knowledge-bases/${encodeURIComponent(props.kbName)}/github-source`, { ...github }); else await post(`/api/knowledge-bases/${encodeURIComponent(props.kbName)}/web-source`, { ...web }); adding.value = false; notice.value = '来源已添加'; await load() } catch (cause) { error.value = cause instanceof Error ? cause.message : '添加失败' } finally { busy.value = false } }
async function sync() { busy.value = true; error.value = ''; try { await post(`/api/knowledge-bases/${encodeURIComponent(props.kbName)}/sync-${endpoint.value}`, {}); notice.value = '同步完成'; await load() } catch (cause) { error.value = cause instanceof Error ? cause.message : '同步失败' } finally { busy.value = false } }
async function remove(id: string) { if (!confirm('删除此来源？已导入的文档处理规则以后不会再同步。')) return; busy.value = true; try { await api(`/api/knowledge-bases/${encodeURIComponent(props.kbName)}/${endpoint.value}-source/${encodeURIComponent(id)}`, { method: 'DELETE' }); notice.value = '来源已删除'; await load() } catch (cause) { error.value = cause instanceof Error ? cause.message : '删除失败' } finally { busy.value = false } }
async function schedule(source: WebSource) { busy.value = true; try { await api(`/api/knowledge-bases/${encodeURIComponent(props.kbName)}/web-source/${encodeURIComponent(source.id)}/schedule`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ auto_sync_enabled: source.auto_sync_enabled, sync_interval_hours: source.sync_interval_hours }) }); notice.value = '同步计划已保存' } catch (cause) { error.value = cause instanceof Error ? cause.message : '保存计划失败' } finally { busy.value = false } }
</script>
<template><section class="kb-section"><header class="kb-section-heading"><div><h2>{{ kind === 'github' ? 'GitHub 来源' : '网页来源' }}</h2><p>{{ kind === 'github' ? '跟踪仓库中的 Markdown 文档，按分支、目录和匹配规则同步。' : '抓取文档网站，并按同步计划更新知识库。' }}</p></div><div><button :disabled="busy || !sources.length" @click="sync"><LegacyIcon name="history" :size="14" />全部同步</button><button v-if="!readOnly" class="primary" @click="adding = !adding"><LegacyIcon name="plus" :size="14" />添加来源</button></div></header><p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="notice" class="notice" role="status">{{ notice }}</p><form v-if="adding" class="kb-source-form" @submit.prevent="add"><template v-if="kind === 'github'"><label>仓库（owner/repo）<input v-model="github.repo" required placeholder="owner/repository"></label><label>分支<input v-model="github.branch" required></label><label>目录（可选）<input v-model="github.path" placeholder="docs"></label><label>文件匹配<input v-model="github.glob" required placeholder="*.md"></label></template><template v-else><label>文档网站 URL<input v-model="web.url" type="url" required placeholder="https://docs.example.com"></label><label>最大深度<input v-model.number="web.max_depth" type="number" min="0" max="10"></label><label>最大页数<input v-model.number="web.max_pages" type="number" min="1" max="5000"></label></template><div><button type="button" @click="adding = false">取消</button><button class="primary" :disabled="busy">添加并同步</button></div></form><p v-if="loading" class="muted">加载中…</p><div v-else-if="!sources.length" class="kb-empty">暂无来源，点击“添加来源”开始。</div><div v-else class="kb-record-list"><article v-for="source in sources" :key="source.id"><div><strong>{{ kind === 'github' ? (source as GitHubSource).repo : (source as WebSource).url }}</strong><p v-if="kind === 'github'">{{ (source as GitHubSource).branch }} · {{ (source as GitHubSource).path || '/' }} · {{ (source as GitHubSource).glob }} · {{ (source as GitHubSource).files_synced }} 个文件</p><p v-else>深度 {{ (source as WebSource).max_depth }} · 最多 {{ (source as WebSource).max_pages }} 页 · 已抓取 {{ (source as WebSource).page_count }} 页</p><small>{{ source.last_sync_status || '尚未同步' }}<template v-if="source.last_synced_at"> · {{ new Date(source.last_synced_at).toLocaleString('zh-CN') }}</template></small><p v-if="source.last_sync_error" class="error">{{ source.last_sync_error }}</p><div v-if="kind === 'web' && !readOnly" class="kb-source-schedule"><label><input v-model="(source as WebSource).auto_sync_enabled" type="checkbox" @change="schedule(source as WebSource)">自动同步</label><label>间隔（小时）<input v-model.number="(source as WebSource).sync_interval_hours" type="number" min="1" max="168" @change="schedule(source as WebSource)"></label></div></div><button v-if="!readOnly" class="danger" :disabled="busy" @click="remove(source.id)">删除</button></article></div></section></template>
